mapper.select:
select delivery_id, task_id, run_id, project_id, provider, channel, pr_number, issue_id,
       idempotency_key, external_id, delivery_status, failure_message,
       attempt_count, next_attempt_at, last_error_code, lease_owner, lease_until,
       last_attempt_time, trigger_source, create_by, create_time, update_by, update_time
from review_delivery_record
where project_id = #{projectId}
  and pr_number = #{prNumber}
  and channel = #{channel}
limit 1


where 1 = 1

    and rdr.project_id = #{projectId}


    and rdr.channel = #{channel}


    and rdr.delivery_status = #{deliveryStatus}


    and rdr.pr_number = #{prNumber}


    and rdr.task_id = #{taskId}


    and coalesce(rdr.last_attempt_time, rdr.create_time) >= #{beginTime}


    and coalesce(rdr.last_attempt_time, rdr.create_time) <= #{endTime}

${params.dataScope}
order by coalesce(rdr.last_attempt_time, rdr.create_time) desc, rdr.delivery_id desc

select count(1)
from review_delivery_record rdr
left join review_project p on p.project_id = rdr.project_id
left join sys_business_system bs on bs.system_id = p.business_system_id
left join sys_dept d on d.dept_id = p.dept_id
left join sys_user owner on owner.user_id = p.owner_user_id
where 1 = 1

    and rdr.project_id = #{projectId}


    and rdr.channel = #{channel}


    and rdr.delivery_status = #{deliveryStatus}


    and rdr.pr_number = #{prNumber}


    and rdr.task_id = #{taskId}


    and coalesce(rdr.last_attempt_time, rdr.create_time) >= #{beginTime}


    and coalesce(rdr.last_attempt_time, rdr.create_time) <= #{endTime}

${params.dataScope}

mapper.update:
update review_delivery_record set task_id = #{taskId}, run_id = #{runId}, external_id = #{externalId}, delivery_status = #{deliveryStatus}, failure_message = #{failureMessage}, attempt_count = attempt_count + 1, last_attempt_time = #{lastAttemptTime}, trigger_source = #{triggerSource},
content_snapshot = #{contentSnapshot},
update_by = #{updateBy}, update_time = sysdate() where idempotency_key = #{idempotencyKey}

update review_delivery_record
set lease_owner = null,
    lease_until = null,
    update_time = sysdate()
where delivery_id = #{deliveryId}
  and lease_owner = #{leaseOwner}
